window.PACK={"book":{"id":"diwan-khansa","title":"ديوان الخنساء","type":"diwan","author":"الخنساء (ت ٢٤هـ)","source":"الموسوعة الشعرية / المكتبة الشاملة عبر مشروع OpenITI","optional":true,"era":"mukhadram","packVersion":"b9aa5cb169a4"},"items":[{"id":"diwan-khansa:1","bookId":"diwan-khansa","type":"poem","seq":1,"chapter":"البحر: بسيط تام","title":"يا عين ما لك لا تبكين تسكابا ؟","page":"","text":"يا عين ما لك لا تبكين تسكابا ؟ … اذ راب دهر وكان الدهر ريابا\nفابكي أخاك لأيتام وأرملة ، … وابكي اخاك اذا جاورت اجنابا\nوابكي اخاك لخيل كالقطاعصبا … فقدن لما ثوى سيبا وانهابا\nيعدو به سابح نهد مراكله … مجلبب بسواد الليل جلبابا\nحتى يصبح أقواما ، يحاربهم ، … أو يسلبوا ، دون صف القوم ، أسلابا\nهو الفتى الكامل الحامي حقيقته ، … مأوى الضريك اذا ما جاء منتابا\nيهدي الرعيل إذا ضاق السبيل بهم ، … نهد التليل لصعب الأمر ركابا\nالمجد حلته ، والجود علته ، … والصدق حوزته ان قرنه هابا\nخطاب محفلة فراج مظلمة … ان هاب معضلة سنى لها بابا\nحمال ألوية ، قطاع أودية ، … شهاد أنجية ، للوتر طلابا\nسم العداة وفكاك العناة اذا … لاقى الوغى لم يكن للموت هيابا"},{"id":"diwan-khansa:2","bookId":"diwan-khansa","type":"poem","seq":2,"chapter":"البحر: طويل","title":"وخرق ، كأنضاء القميص دوية ،","page":"","text":"وخرق ، كأنضاء القميص دوية ، … مخوف رداه ما يقيم به ركب\nقطعت بمجذام الرواح كانها … اذا حط عنها كورها جمل صعب\nيعاتبها في بعض ما أذنبت له ، … فيضربها ، حينا ، وليس لها ذنب\nوقد جعلت في نفسها ان تخافه … وليس لها منه سلام ولا حرب\nفطرت بها ، حتى إذا اشتد ظمؤها ، … وحب إلى القوم الإناخة والشرب\nانخت الى مظلومة غير مسكن … حواملها عوج ، وأفنانها رطب\nفناطا ليها سيفه ورداءه … وجاء إلى أفياء ما علق الركب\nفأغفى قليلا ، ثم طار برحلها ، … ليكسب مجدا ، أو يحور لها نهب\nفثارت تباري أعوجيا مصدرا ، … طويل عذار الخد ، جؤجؤه رحب"},{"id":"diwan-khansa:3","bookId":"diwan-khansa","type":"poem","seq":3,"chapter":"قصائد","title":"يا ابن الشريد ، على تنائي بيننا ،","page":"","text":"يا ابن الشريد ، على تنائي بيننا ، … حييت ، غير مقبح ، مكباب\nفكه على خير الغذاء اذاغدت … شهباء تقطع بالي الاطناب\nأرج العطاف ، مهفهف ، نعم الفتى … متسهل في الأهل والأجناب\nحامي الحقيق تخاله عند الوغى … اسدا بيشة كاشر الأنياب\nاسدا تناذره الرفاق ضبارما … شثن البراثن لاحق الأقراب\nفلئن هلكت لقد غنيت سميذعا … محض الضريبة طيب الأثواب\nضخم الدسيعة بالندى متدفقا … مأوى اليتيم وغاية المنتاب"},{"id":"diwan-khansa:4","bookId":"diwan-khansa","type":"poem","seq":4,"chapter":"البحر: وافر تام","title":"ارقت ونام عن سهري صحابي","page":"","text":"ارقت ونام عن سهري صحابي … كأن النار مشعلة ثيابي\nإذا نجم تغور كلفتني … خوالد ما تؤوب إلى مآب\nفقد خلى ابو اوفى خلالا … علي فكلها دخلت شعابي"},{"id":"diwan-khansa:5","bookId":"diwan-khansa","type":"poem","seq":5,"chapter":"البحر: بسيط تام","title":"ما بال عينيك منها دمعها سرب","page":"","text":"ما بال عينيك منها دمعها سرب … أراعها حزن أم عادها طرب\nأم ذكر صخر بعيد النوم هيجها … فالدمع منها عليه الدهر ينسكب\nيا لهف نفسي على صخر إذا ركبت … خيل لخيل تنادي ثم تضطرب\nقد كان حصنا شديد الركن ممتنعا … ليثا إذا نزل الفتيان أو ركبوا\nأغر ، أزهر ، مثل البدر صورته ، … صاف ، عتيق ، فما في وجهه ندب\nيا فارس الخيل إذ شدت رحائلها … ومطعم الجوع الهلكى إذا سغبوا\nكم من ضرائك هلاك وارملة … حلوا لديك فزالت عنهم الكرب\nسقيا لقبرك من قبر ولا برحت … جود الرواعد تسقيه وتحتلب\nماذا تضمن من جود ومن كرم … ومن خلائق ما فيهن مقتضب"},{"id":"diwan-khansa:6","bookId":"diwan-khansa","type":"poem","seq":6,"chapter":"البحر: بسيط تام","title":"يا عين جودي بدمع منك مسكوب","page":"","text":"يا عين جودي بدمع منك مسكوب … كلؤلؤ جال في الأسماط مثقوب\nاني تذكرته والليل معتكر … ففي فؤادي صدع غير مشعوب\nنعم الفتى كان للأضياف إذ نزلوا … وسائل حل بعد النوم محروب\nكم من مناد دعا والليل مكتنع … نفست عنه حبال الموت مكروب\nومن اسير بلا شكر جزاك به … بساعديه كلوم غير تجليب\nفككته ، ومقال قلته حسن … بعد المقالة لم يؤبن بتكذيب"},{"id":"diwan-khansa:7","bookId":"diwan-khansa","type":"poem","seq":7,"chapter":"البحر: طويل","title":"تقول نساء : شبت من غير كبرة ،","page":"","text":"تقول نساء : شبت من غير كبرة ، … وايسر مما قد لقيت يشيب\nأقول : أبا حسان : لا العيش طيب … وكيف وقد افردت منك يطيب\nفتى السن كهل الحلم لا متسرع … ولا جامد جعد اليدين جديب\nأخو الفضل لا باغ عليه لفضله … ولا هو خرق في الوجوه قطوب\nاذا ذكر الناس السماح من امرئ … وأكرم أو قال الصواب خطيب\nذكرتك فاستعبرت والصدر كاظم … على غصة منها الفؤاد يذوب\nلعمري لقد أوهيت قلبي عن العزا … وطأطأت رأسي والفؤاد كئيب\nلقد قصمت مني قناة صليبة … ويقصم عود النبع وهو صليب"},{"id":"diwan-khansa:8","bookId":"diwan-khansa","type":"poem","seq":8,"chapter":"البحر: طويل","title":"أعين ألا فابكي لصخر بدرة","page":"","text":"أعين ألا فابكي لصخر بدرة … اذا الخيل من طول الوجيف اقشعرت\nاذا زجروها في الصريخ وطابقت … طباق كلاب في الهراش وهرت\nشددت عصاب الحرب اذ هي مانع … فألقت برجليها مريا فدرت\nوكانت اذا ما رامها قبل حالب … تقته بإيزاغ دما واقمطرت\nوكان ابو حسان صخر اصابها … فارغثها بالرمح حتى اقرت\nكراهية والصبر منك سجية … إذا ما رحى الحرب العوان استدرت\nاقاموا جنابي رأسها وترافدوا … على صعبها يوم الوغى فاسبطرت\nعوان ضروس ما ينادى وليدها … تلقح بالمران حتى استمرت\nحلفت على أهل اللواء ليوضعن … فما أحنثتك الخيل حتى أبرت\nوخيل تنادى لا هوادة بينها … مررت لها دون السوام ومرت\nكان مدلا من اسود تبالة … يكون لها حيث استدارت وكرت"},{"id":"diwan-khansa:9","bookId":"diwan-khansa","type":"poem","seq":9,"chapter":"البحر: طويل","title":"لهفي على صخر فاني ارى له","page":"","text":"لهفي على صخر فاني ارى له … نوافل من معروفه قد تولت\nولهفي على صخر لقد كان عصمة … لمولاه إن نعل بمولاه زلت\nيعود على مولاه منه برأفة … اذا ما الموالي من اخيها تخلت\nوكنت إذا كف أتتك عديمة … ترجي نوالا من سحابك بلت\nومختنق راخى ابن عمر وخناقه … وغمته عن وجهه فتجلت\nوظاعنة في الحي لولا عطاؤه … غداة غد من اهلها ما استقلت\nوكنت لنا عيشا وظل ربابة … إذا نحن شئنا بالنوال استهلت\nفتى كان ذا حلم أصيل وتؤدة … اذا ما الحبى من طائف الجهل حلت\nوما كر الا كان اول طاعن … ولا أبصرته الخيل إلا اقشعرت\nفيدرك ثأرا ثم لم يخطه الغنى … فمثل أخي يوما به العين قرت\nفإن طلبوا وترا بدا بتراتهم … ويصبر يحميهم إذا الخيل ولت\nفلست ازرا بعده برزية … فاذكره الا سلت وتجلت"},{"id":"diwan-khansa:10","bookId":"diwan-khansa","type":"poem","seq":10,"chapter":"البحر: وافر تام","title":"ألا يا عين فانهمري ، وقلت ألا يا عين فانهمري ، وقلت","page":"","text":"ألا يا عين فانهمري ، وقلت ألا يا عين فانهمري ، وقلت … لمرزئة اصبت بها تولت\nلمرزئة كان النفس منها … بعيد النوم تشعل يوم غلت\nألا يا عين ويحك أسعديني … فقد عظمت مصيبته وجلت\nمصيبته علي وروعتني … فقد خصت مصيبته وعمت\nلو أن الكف تقبل في فداه … بذلت يدي اليمين له فشلت\nكما والى عليينا من نداه ، … وشاد لنا المكارم فاستهلت\nفلم ينزع وما قصرت يداه … ولم يبلغ ثنائي حيث حلت"},{"id":"diwan-khansa:11","bookId":"diwan-khansa","type":"poem","seq":11,"chapter":"البحر: مجزوء الكامل","title":"يا عين جودي بالدموع","page":"","text":"يا عين جودي بالدموع … المستهلات السوافح\nفيضا كما فاضت غروب … ب المترعات من النواضح\nوابكي لصخر اذ ثوى … بين الضريحة والصفائح\nرمسا لدى جدث تذيع م … بتربه هوج النوافح\nالسيد الجحجاح وابن … السادة الشم الجحاجح\nالحامل الثقل المهم م … من الملمات الفوادح\nالجابر العظم الكسير … من المهاصر والممانح\nالواهب المئة الهجان … ن من الخناذيذ السوابح\nالغافر الذنب العظيم … لذي القرابة والممالح\nبتعمد منه وحلم م … حين يبغي الحلم راجح\nذاك الذي كنا به … نشفي المراض من الجوانح\nويرد بادرة العدو … ونخوة الشنف المكاشح\nفأصابنا ريب الزمان … ن فنالنا منه بناطح\nفكانما ام الزما … نحورنا بمدى الذبائح\nفنساؤنا يندبن نوحا … حا بعد هادية النوائح\nيحنن بعد كرى العيو … ن حنين والهة قوامح\nشعثت شواحب لا ينين … اذا ونى ليل النوائح\nيندبن فقد أخي الندى … والخير والشيم الصوالح\nوالجود والأيدي الطوال … المستفيضات السوامح\nفالآن نحن ومن سوانا … نامثل اسنان القوارح"},{"id":"diwan-khansa:12","bookId":"diwan-khansa","type":"poem","seq":12,"chapter":"البحر: طويل","title":"ذري عنك أقوال الضلال ، كفى بنا","page":"","text":"ذري عنك أقوال الضلال ، كفى بنا … لكبش الوغى في اليوم والأمس ناطحا\nفخالد أولى بالتعذر منكم … غداة علا نهجا من الحق واضحا\nعليكم باذن الله يرجي مصمما … سوانح لا تكبو لها وبوارحا\nنعوا مالكا بالتاج لما هبطنه … عوابس في هابي الغبار كوالحا\nفإن تك قد أبكتك سلمى بمالك … تركنا عليه نائحات ونائحا"},{"id":"diwan-khansa:13","bookId":"diwan-khansa","type":"poem","seq":13,"chapter":"البحر: خفيف تام","title":"لا تخل أنني لقيت رواحا","page":"","text":"لا تخل أنني لقيت رواحا … بعد صخر حتى أثبن نواحا\nمن ضميري بلوعة الحزن حتى … نكأ الحزن في فؤادي فقاحا\nلا تخلني اني نسيت ولا بل … فؤادي ولو شربت القراحا\nذكر صخر إذا ذكرت نداه … عيل صبري برزئه ثم باحا\nان في الصدر اربعا يتجاوبن … م حنينا حتى كسرن الجناحا\nدق عظمي وهاض مني جناحي … هلك صخر فما أطيق براحا\nمن لضيف يحل بالحي عان … بعد صخر إذا دعاه صياحا\nوعليه ارامل الحي والسفر م … ومعترهم به قد ألاحا\nوعطايا يهزها بسماح … وطماح لمن اراد طماحا\nظفر بالامور جلد نجيب … واذا ما سما لحرب اباحا\nوبحلم إذا الجهول اعتراه … يردع الجهل بعد ما قد اشاحا\nانني قد علمت وجدك بالحمد م … واطلاقك العناة سماحا\nفارس يضرب الكتيبة بالسيف م … اذا ازدف العويل الصياحا\nيقبل الطعن للنحور بشزر … حين يسمو حتى يلين الجراحا\nمقبلات حتى يولين عنه … مدبرات وما يرذن كفاحا\nكم طريد قد سكن الجأش منه … كان يدعو بصفهن صراحا\nفارس الحرب والمعمم فيها … مدره الحرب حين يلقى نطاحا"},{"id":"diwan-khansa:14","bookId":"diwan-khansa","type":"poem","seq":14,"chapter":"البحر: طويل","title":"جرى لي طير في حمام حذرته","page":"","text":"جرى لي طير في حمام حذرته … عليك ابن عمر ومن سنيح وبارح\nفلم ينج صخرا ما حذرت وغاله … مواقع غاد للمنون ورائح\nرهينة رمس قد تجر ذيولها … عليه سوافي الرامسات البوارح\nفيا عين بكي لأمرىء طار ذكره … له تبكي عين الراكضات السوابح\nوكل طويل المتن اسمر ذابل … وكل عتيق في جياد الصفائح\nوكل دلاص كالاضاة مذالة … وكل جواد بين العتق قارح\nوكل ذمول كالفنيق شملة … وكل سريع ، آخر الليل ، آزح\nوللجار يوما إن دعا لمضيفة … دعا مستغيثا اولا بالجوابح\nأخو الحزم في الهيجاء والعزم في التي … لوقعتها يسود بيض المسايح\nحسيب لبيب متلف ما افاده … مبيح تلاد المستغش المكاشح"},{"id":"diwan-khansa:15","bookId":"diwan-khansa","type":"poem","seq":15,"chapter":"البحر: متقارب تام","title":"أعيني جودا ولا تجمدا","page":"","text":"أعيني جودا ولا تجمدا … ألا تبكيان لصخر الندى ؟\nألا تبكيان الجريء الجميل … ألا تبكيان الفتى السيدا ؟\nطويل النجاد رفيع العما … ساد عشيرته أمردا\nإذا القوم مدوا بأيديهم … إلى المجد مد إليه يدا\nفنال الذي فوق أيديهم … من المجد ثم مضى مصعدا\nيكلفه القوم ما عالهم … وإن كان أصغرهم مولدا\nترى المجد يهوي الى بيته … يرى افضل الكسب ان يحمدا\nوان ذكر المجد الفيته … تأزر بالمجد ثم ارتدى"},{"id":"diwan-khansa:16","bookId":"diwan-khansa","type":"poem","seq":16,"chapter":"البحر: وافر تام","title":"بكت عيني وعاودت السهودا","page":"","text":"بكت عيني وعاودت السهودا … وبت الليل جانحة عميدا\nلذكرى معشر ولوا وخلوا … علينا من خلافتهم فقودا\nووافوا ظمء خامسة فامسوا … مع الماضين قد تبعوا ثمودا\nفكم من فارس لك أم عمر و … يحوط سنانه الانس الحريدا\nكصخر او معاوية بن عمر و … اذا كانت وجوه القوم سودا\nيرد الخيل دامية كلاها … جدير يوم هيجا أن يصيدا\nيكبون العشار لمن اتاهم … اذا لم تحسب المئة الوليدا"},{"id":"diwan-khansa:17","bookId":"diwan-khansa","type":"poem","seq":17,"chapter":"البحر: طويل","title":"لا شيء يبقى غير وجه مليكنا","page":"","text":"لا شيء يبقى غير وجه مليكنا … ولست أرى شيئا على الدهر خالدا\nألا إن يوم ابن الشريد ورهطه … أباد جفانا والقدور الرواكدا\nهم يملأون لليتيم اناء ه … وهم ينجزون للخليل المواعدا\nالا ابلغا عني سليما وعامرا … ومن كان من عليا هوازن شاهدا\nبأن بني ذبيان قد أرصدوا لكم … إذا ما تلاقيتم بأن لا تعاودا\nفلا يقربن الأرض إلا مسارق … يخاف خميسا مطلع الشمس حاردا\nعلى كل جرداء النسالة ضامر … بآخر ليل ما ضفزن الحدائدا\nفقد زاح عنا اللوم اذ تركوا لنا … اروما فآراما فماء بواردا\nونحن قتلنا هاشما وابن اخته … ولا صلح حتى نستقيد الخرائدا\nفقد جرت العادات أنا لدى الوغى … سنظفر والانسان يبغي الفوائدا"},{"id":"diwan-khansa:18","bookId":"diwan-khansa","type":"poem","seq":18,"chapter":"البحر: بسيط تام","title":"ابكي لصخر اذا ناحت مطوقة","page":"","text":"ابكي لصخر اذا ناحت مطوقة … حمامة ، شجوها ، ورقاء بالوادي\nإذا تلأم في زغف مضاعفة … وصارم مثل لون الملح جراد\nونبعة ذات ارنان وولولة … ومارن العود لا كز ولا عاد\nسمح الخليقة لا نكس ولا غمر … بل باسل مثل ليث الغابة العادي\nمن أسد بيشة يحمي الخل ذي لبد … من اهله الحاضر الآذنين والبادي\nوالمشبع القوم إن هبت مصرصرة … نكباء مغبرة هبت بصراد"},{"id":"diwan-khansa:19","bookId":"diwan-khansa","type":"poem","seq":19,"chapter":"البحر: مجزوء الكامل","title":"يا عين جودي بالدموع","page":"","text":"يا عين جودي بالدموع … فقد جفت عنك المراود\nوابكي لصخر انه … شق الفؤاد لما يكابد\nالمستضاف من السنين … إذا قسا منها المحارد\nحين الرياح بلائل … نكب هوائجها صوارد\nينفين عن ليط السما … ظلائلا والماء جامد\nمزقا تطردها الريا … كأنها خرق طرائد\nوالمال عند ذوي البقية … والغنى خذم شرائد\nفيفك كربة من تمخخ … نقية الدول الجهائد\nحتى يؤوب بما يؤوب … كثير فضل العرف حامد\nونداك محتضر ونو … رك في دجى الظلماء واقد\nلو ترسل الإبل الظماء … يسمن ليس لهن قائد\nلتيممتك يدلها … جدواك والسبل الموارد\nوالناس سابلة اليك م … فصادر بغنى ووارد\nيغشون منك غطامطا … جاشت بوابله الرواعد\nيا ابن القروم ذوي الحجى … وابن الخضارمة المرافد\nوابن المهائر للمهائر … ئر زانها الشيم المواجد\nوحماة من يدعى اذا … ما طار عند الموت عارد\nومعاصم للهالكين م … وساسة قدما محاشد"},{"id":"diwan-khansa:20","bookId":"diwan-khansa","type":"poem","seq":20,"chapter":"البحر: وافر تام","title":"أهاج لك الدموع على ابن عمر و","page":"","text":"أهاج لك الدموع على ابن عمر و … مصائب قد رزئت بها فجودي\nبسجل منك منحدر عليه … فما ينفك مثل عدا الفريد\nعلى فرع رزئت به خناس … طويل الباع فياض حميد\nجليد كان خير بني سليم … كريمهم المسود والمسود\nأبو حسان كان ثمال قومي … فأصبح ثاويا بين اللحود\nرهين بلى ، وكل فتى سيبلى … فأذري الدمع بالسكب المجود\nفأقسم لو بقيت لكنت فينا … عديدا لا يكاثر بالعديد\nولكن الحوادث طارقات … لها صرف على الرجل الجليد\nفإن تك قد أتتك فلا تنادي … فقد اودت بفياض مجيد\nجليد حازم قدما اتاه … صروف الدهر بعد بني ثمود\nوعادا قد علاها الدهر قسرا … وحمير والجنود مع الجنود\nفلا يبعد أبو حسان صخر … وحل برمسه طير السعود"},{"id":"diwan-khansa:21","bookId":"diwan-khansa","type":"poem","seq":21,"chapter":"البحر: بسيط تام","title":"عيني جودا بدمع منكما جودا","page":"","text":"عيني جودا بدمع منكما جودا … جودا ولا تعدا في اليوم موعودا\nهل تدريان على من ذا سبلتكما … على ابن امي ابيت الليل معمودا\nدارت بنا الارض او كادت تدور بنا … يا لهف نفسي فقد لاقيت صنديدا\nيا عين فابكي فتى محضا ضرائبه … صعبا مراقبه سهلا اذا ريدا\nلايأخذ الخسف في قوم فيغضبهم … ولا تراه اذا ما قام محدودا\nولا يقوم إلى ابن العم يشتمه … ولا يدب إلى الجارات تخويدا\nكأنما خلق الرحمان صورته … دينار عين يراه الناس منقودا\nإذهب حريبا جزاك الله جنته … عنا وخلدت في الفردوس تخليدا\nقد عشت فينا ولا ترمى بفاحشة … حتى توفاك رب الناس محمودا"},{"id":"diwan-khansa:22","bookId":"diwan-khansa","type":"poem","seq":22,"chapter":"البحر: بسيط تام","title":"ضاقت بي الارض وانقضت محارمها","page":"","text":"ضاقت بي الارض وانقضت محارمها … حتى تخاشعت الاعلام والبيد\nوقائلين تعزي عن تذكره … فالصبر ليس لامر الله مردود\nيا صخر قد كنت بدرا يستضاء به … فقد ثوى يوم مت المجد والجود\nفاليوم امسيت لا يرجوك ذو امل … لما هلكت وحوض الموت مورود\nورب ثغر مهول خضت غمرته … بالمقربات عليها الفتية الصيد\nنصبت للقوم فيه فصل اعينهم … مثل الشهاب وهى منهم عباديد"},{"id":"diwan-khansa:23","bookId":"diwan-khansa","type":"poem","seq":23,"chapter":"البحر: كامل تام","title":"يا ابن الشريد وخير قيس كلها","page":"","text":"يا ابن الشريد وخير قيس كلها … خلفتني في حسرة وتلبد\nفلأبكينك ما سمعت حمامة … تدعو هديلا في فروع الفرقد\nانت المهند من سليم في العلى … والفرع لم يسب الكرام بمشهد\nقد كنت حصنا للعشيرة كلها … وخطيبها عند الهمام الاصيد\nفاذهب ولا تبعد وكل معمر … سيذوق كأس منية بتنكد\nلله در بني نهاسر إنهم … هدموا العمود وأدركوا بالأسود\nضخم الدسيعة ماجدا أعراقه … كالبدر أو طلعة كالأسعد"},{"id":"diwan-khansa:24","bookId":"diwan-khansa","type":"poem","seq":24,"chapter":"البحر: طويل","title":"ابكي ابي عمرا بعين غزيرة","page":"","text":"ابكي ابي عمرا بعين غزيرة … قليل اذا نام الخلي هجودها\nوصنوي لا أنسى معاوية الذي … له من سراة الحرتين وفودها\nوصخرا ومن ذا مثل صخر اذا غدا … بساحته الآطال قزم يقودها\nفذلك يا هند الرزية فاعلمي … ونيران حرب حين شب وقودها"},{"id":"diwan-khansa:25","bookId":"diwan-khansa","type":"poem","seq":25,"chapter":"البحر: وافر تام","title":"ألا يا عين فانهمري بغدر","page":"","text":"ألا يا عين فانهمري بغدر … وفيضي فيضة من غير نزر\nولا تعدي عزاء بعد صخر … فقد غلب العزاء وعيل صبري\nلمرزئة كان الجوف منها … بعيد النوم يشعر حر جمر\nعلى صخر وأي فتى كصخر … لعان عائل غلق بوتر\nوللخصم الالد اذا تعدى … ليأخذ حق مقهور بقسر\nوللأضياف اذ طرقوا هدوءا … وللكل المكل وكل سفر\nاذا نزلت بهم سنة جماد … أبي الدر لم تكسع بغبر\nهناك يكون غيث حيا تلاقى … نداه في جناب غير وغر\nواحيا من مخبأة كعاب … وأشجع من أبي شبل هزبر\nهريت الشدق رئبال اذا ما … عدا لم تنه عدوته بزجر\nضبارمة توسد ساعديه … على طرق الغزاة وكل بحر\nتدين الخادرات له إذا ما … سمعن زئيره في كل فجر\nقواعد ما يلم بها عريب … لعسر في الزمان ولا ليسر\nفإما يمس في جدث مقيما … بمعترك من الأرواح قفر\nفقد يعصوصب الجادون منه … باروع ماجد الاعراق غمر\nاذا ما الضيق حل الى ذراه … تلقاه بوجه غير بسر\nتفرج بالندى الأبواب عنه … ولا يكتن دونهم بستر\nدهتني الحادثات به فأمست … علي همومها تغدو وتسري\nلو ان الدهر متخذ خليلا … لكان خليله صخر بن عمرو"},{"id":"diwan-khansa:26","bookId":"diwan-khansa","type":"poem","seq":26,"chapter":"البحر: بسيط تام","title":"قذى بعينك ام بالعين عوار","page":"","text":"قذى بعينك ام بالعين عوار … ام ذرفت اذخلت من اهلها الدار\nكأن عيني لذكراه إذا خطرت … فيض يسيل على الخدين مدرار\nتبكي لصخر هي العبرى وقد ولهت … ودونه من جديد الترب استار\nتبكي خناس فما تنفك ما عمرت … لها عليه رنين وهي مفتار\nتبكي خناس على صخر وحق لها … اذ رابها الدهر ان الدهر ضرار\nلا بد من ميتة في صرفها عبر … والدهر في صرفه حول واطوار\nقد كان فيكم ابو عمر ويسودكم … نعم المعمم للداعين نصار\nصلب النحيزة وهاب اذا منعوا … وفي الحروب جريء الصدر مهصار\nيا صخر وراد ماء قد تناذره … أهل الموارد ما في ورده عار\nمشى السبنتى إلى هيجاء معضلة … له سلاحان : أنياب وأظفار\nوما عجول على بو تطيف به … لها حنينان : إعلان وإسرار\nترتع ما رتعت ، حتى إذا ادكرت … فانما هي اقبال وادبار\nلا تسمن الدهر في ارض وان رتعت … فانما هي تحنان وتسجار\nيوما بأوجد مني يوم فارقني … صخر وللدهر احلاء وامرار\nوإن صخرا لوالينا وسيدنا … وإن صخرا إذا نشتو لنحار\nوإن صخرا لمقدام إذا ركبوا … وإن صخرا إذا جاعوا لعقار\nوإن صخرا لتأتم الهداة به … كأنه علم في رأسه نار\nجلد جميل المحيا كامل ورع … وللحروب غداة الروع مسعار\nحمال ألوية هباط أودية … شهاد أندية للجيش جرار\nفقلت لما رأيت الدهر ليس له … معاتب وحده يسدي ونيار\nلقد نعى ابن نهيك لي اخا ثقة … كانت ترجم عنه قبل اخبار\nفبت ساهرة للنجم ارقبه … حتى أتى دون غور النجم أستار\nلم تره جارة يمشي بساحتها … لريبة حين يخلي بيته الجار\nولا تراه وما في البيت يأكله … لكنه بارز بالصحن مهمار\nومطعم القوم شحما عند مسغبهم … وفي الجدوب كريم الجد ميسار\nقد كان خالصتي من كل ذي نسب … فقد اصيب فما للعيش اوطار\nمثل الرديني لم تنفد شبيبته … كأنه تحت طي البرد أسوار\nجهم المحيا تضيء الليل صورته … آباؤه من طوال السمك أحرار\nمورث المجد ميمون نقيبته … ضخم الدسيعة في العزاء مغوار\nفرع لفرع كريم غير مؤتشب … جلد المريرة عند الجمع فخار\nفي جوف لحد مقيم قد تضمنه … في رمسه مقمطرات واحجار\nطلق اليدين لفعل الخير ذو فجر … ضخم الدسيعة بالخيرات أمار\nليبكه مقتر أفنى حريبته … دهر وحالفه بؤس وإقتار\nورفقة حار حاديهم بمهلكة … كأن ظلمتها في الطخية القار\nلا يمنع القوم إن سالوه خلعته … ولا يجاوزه بالليل مرار"},{"id":"diwan-khansa:27","bookId":"diwan-khansa","type":"poem","seq":27,"chapter":"البحر: طويل","title":"أعيني هلا تبكيان على صخر","page":"","text":"أعيني هلا تبكيان على صخر … بدمع حثيث لا بكيء ولا نزر\nوتستفرغان الدمع أو تذريانه … على ذي الندى والجود والسيد الغمر\nفما لكما عن ذي يمينين فابكيا … عليه مع الباكي المسلب من صبر\nكأن لم يقل أهلا لطالب حاجة … وكان بليج الوجه منشرح الصدر\nولم يغد في خيل مجنبة القنا … ليروي أطراف الردينية السمر\nفشأن المنايا اذ اصابك ريبها … لتغدو على الفتيان بعدك أو تسري\nفمن يضمن المعروف في صلب ماله … ضمانك أو يقري الضيوف كما تقري\n … جراد زفته ريح نجد إلى\nوكائن قرنت الحق من ثوب صفوة … ومن سابح طرف ومن كاعب بكر\nوقائلة والنعش قد فات خطوها … لتدركه : يا لهف نفسي على صخر\nألا ثكلت أم الذين مشوا به … إلى القبر ماذا يحملون إلى القبر\nوماذا يواري القبر تحت ترابه … من الخير يا بؤس الحوادث والدهر\nوم الحزم في العزاء والجود والندى … غداة يرى حلف اليسارة والعسر\nلقد كان في كل الأمور مهذبا … جليل الايادي لا ينهنه بالزجر\nوان تلقه في الشرب لا تلقى فاحشا … ولا ناكثا عقد السرائر والصبر\nفلا يبعدن قبر تضمن شخصه … وجاد عليه كل واكفة القطر"},{"id":"diwan-khansa:28","bookId":"diwan-khansa","type":"poem","seq":28,"chapter":"البحر: سريع","title":"إن كنت عن وجدك لم تقصري","page":"","text":"إن كنت عن وجدك لم تقصري … او كنت في الأسوة لم تعذري\nفإن في العقدة من يلبن … عبر السرى في القلص الضمر\nوصاحب قلت له خائف … إنك للخيل بمستنظر\nإنك داع بكبير إذا … وافيت أعلى مرقب فانظر\nفآنسن من ساعة فارسا … يخب ادنى بقع المنظر\nفاولج السوط على حوشب … أجرد مثل الصدع الأعفر\nتنبطه الساق بشدكما … مال هجير الرجل الاعسر"},{"id":"diwan-khansa:29","bookId":"diwan-khansa","type":"poem","seq":29,"chapter":"البحر: متقارب تام","title":"ذكرت أخي بعد نوم الخلي","page":"","text":"ذكرت أخي بعد نوم الخلي … فانحدر الدمع مني انحدارا\nوخيل لبست لأبطالها … شليلا ودمرت قوما دمارا\nتصيد بالرمح ريعانها … وتهتصر الكبش منها اهتصارا\nفألحمتها القوم تحت الوغى … وأرسلت مهرك فيها فغارا\nيقين وتحسبه قافلا … إذا طابقت وغشين الحرارا\nفذلك في الجد مكروهه … وفي السلم تلهو وترخي الإزارا\nوهاجرة حرها صاخد … جعلت رداءك فيها خمارا\nلتدرك شأوا على قربه … وتكسب حمدا وتحمي الذمارا\nوتروي السنان وتردي الكمي … كمرجل طباخة حين فارا\nوتغشي الخيول حياض النجيع … وتعطي الجزيل وتردي العشارا\nكان القتود اذا شدها … على ذي وسوم تباري صوارا\nتمكن في دفء ارطائه … أهاج العشي عليه فثارا ؟\nفدار فلما رأي سربها … احس قنيصا قريبا فطارا\nيشقق سرباله هاجرا … من الشد لما أجد الفرارا\nفبات يقنص ابطالها … وينعصر الماء منه انعصارا"},{"id":"diwan-khansa:30","bookId":"diwan-khansa","type":"poem","seq":30,"chapter":"البحر: كامل تام","title":"طرق النعي على صفينة غدوة","page":"","text":"طرق النعي على صفينة غدوة … ونعى المعمم من بني عمرو\nحامي الحقيقة والمجير إذا … ما خيف حد نوائب الدهر\nالحي يعلم أن جفنته … تغدو غداة الريح أو تسري\nفإذا أضاء وجاش مرجله … فلنعم رب النار والقدر\nابلغ موالية فقد رزئوا … مولى يريشهم ولا يشري\nيكفي حماتهم ويعطي لهم … مئة من العشرين والعشر\nتروي سنان الرمح طعنته … والخيل قد خاضت دما يجري\nقد كان مأوى كل أرملة … ومقيل عثرة كل ذي عذر\nتلقى عيالهم نوافله … فتصيب ذا الميسور والعسر"},{"id":"diwan-khansa:31","bookId":"diwan-khansa","type":"poem","seq":31,"chapter":"البحر: كامل تام","title":"أبني سليم إن لقيتم فقعسا","page":"","text":"أبني سليم إن لقيتم فقعسا … في محبس ضنك إلى وعر\nفالقوهم بسيوفكم ورماحكم … وبنضحة في الليل كالقطر\nحتى تفضوا جمعهم وتذكروا … صخرا ومصرعه بلا ثأر\nوفوارسا منا هنالك قتلوا … في عثرة كانت من الدهر\nلاقى ربيعة في الوغى فأصابه … طعن بجائفة إلى الصدر\nبمقوم لدن الكعوب سنانه … ذرب الشياة كقادم النسر\nونجا ربيعة يوم ذلك مرهقا … لا يأتلي في جوده يجري\nفأتت به ، أسل الأسنة ، ضامر … مثل العقاب غدت مع الوكر\nولقد اخذنا خالدا فاجاره … عوف وأطلقه على قدر\nولقد تدارك رأينا في خالد … ما ساء خيلا آخر الدهر"},{"id":"diwan-khansa:32","bookId":"diwan-khansa","type":"poem","seq":32,"chapter":"البحر: بسيط تام","title":"يا عين فيضي بدمع منك مغزار","page":"","text":"يا عين فيضي بدمع منك مغزار … وابكي لصخر بدمع منك مدرار\nاني ارقت فبت الليل ساهرة … كانما كحلت عيني بعوار\nارعى النجوم وما كلفت رعيتها … وتارة أتغشى فضل أطماري\nوقد سمعت فلم أبهج به خبرا … مخبرا قام ينمي رجع أخبار\nقال ابن امك ثاو بالضريح وقد … سووا عليه بالواح واحجار\nفاذهب فلا يبعدنك الله من رجل … مناع ضيم وطلاب باوتار\nقد كنت تحمل قلبا غير مهتضم … مركبا في نصاب غير خوار\nمثل السنان تضيء الليل صورته … جلد المريرة حر وابن احرار\nابكي فتى الحي نالته منيته … وكل نفس الى وقت ومقدار\nوسوف أبكيك ما ناحت مطوقة … وما اضاءت نجوم الليل للساري\nولا أسالم قوما كنت حربهم … حتى تعود بياضا جؤنة القار\nابلغ سليما وعوفا ان لقيتهم … عميمة من نداء غير إسرار\nأعني الذين إليهم كان منزله … هل تعرفون ذمام الضيف والجار ؟\nلو منكم كان فينا لم ينل ابدا … حتى تلاقى أمور ذات آثار\nكأن ابن عمتكم حقا وضيفكم … فيكم فلم تدفعوا عنه بإخفار\nشدوا المآزر حتى يستدف لكم … وشمروا إنها أيام تشمار\nوابكوا فتى البأس وافته منيته … في كل نائبة نابت وأقدار\nلا نوم حتى تقودوا الخيل عابسة … ينبذن طرحا بمهرات وأمهار\nاوتحفروا حفرة فالموت مكتنع … عند البيوت حصينا وابن سيار\nاو ترحضوا عنكم عارا تجللكم … رحض العوارك حيضا عند أطهار\nوالحرب قد ركبت حدباء نافرة … حلت على طبق من ظهرها عار\nكأنهم يوم راموه بأجمعهم … راموا الشكيمة من ذي لبدة ضار\nحامي العرين لدى الهيجاء مضطلع … يفري الرجال بانياب واظفار\nحتى تفرجت الآلاف عن رجل … ماض على الهول هاد غير محيار\nتجيش منه فويق الثدي جائفة … بمزبد من نجيع الجوف فوار"},{"id":"diwan-khansa:33","bookId":"diwan-khansa","type":"poem","seq":33,"chapter":"البحر: رمل تام","title":"عين فابكي لي على صخر إذا","page":"","text":"عين فابكي لي على صخر إذا … علت الشفرة أثباج الجزر\nيشبع القوم من الشحم إذا … الوت الريح باغصان الشجر\nواذا ما البيض يمشين معا … كبنات الماء في الضحل الكدر\nجانحات تحت أطراف القنا … باديات السوق في فج حذر\nيطعن الطعنة لا يرقئها … رقية الراقي ولا عصب الخمر"},{"id":"diwan-khansa:34","bookId":"diwan-khansa","type":"poem","seq":34,"chapter":"البحر: طويل","title":"كأن ابن عمر ولم يصبح لغارة","page":"","text":"كأن ابن عمر ولم يصبح لغارة … بخيل ولم يعمل نجائب ضمرا\nولم يجز إخوان الصفاء ويكتني … عجاجا اثارته السنابك اكدرا\nولم يبن في حرالهواجر مرة … لفتيته ظلا رداء محبرا\nفبكوا على صخر بن عمر وفإنه … يسير اذا ما الدهر بالناس اعسرا\nيجود ويحلو حين يطلب خيره … ومرا إذا يبغي المرارة ممقرا\nفخنساء تبكي في الظلام حزينة … وتدعو أخاها لا يجيب معفرا"},{"id":"diwan-khansa:35","bookId":"diwan-khansa","type":"poem","seq":35,"chapter":"البحر: مجزوء الكامل","title":"يا عين جودي بالدموع","page":"","text":"يا عين جودي بالدموع … ع على الفتى القرم الاغر\nأبيض أبلج وجهه … كالشمس في خير البشر\nوالشمس كاسفة لمهلكه م … وما اتسق القمر\nوالانس تبكي ولها … والجن تسعد من سمر\nوالوحش تبكي شجوها … لما اتى عنه الخبر\nالمدره الفياض يحمل … عن عشيرته الكبر\nيعطي الجزيل ولا يمن … م وليس شيمته العسر\nويلي عليه ويلة … اصبحت حصني منكسر"},{"id":"diwan-khansa:36","bookId":"diwan-khansa","type":"poem","seq":36,"chapter":"البحر: بسيط تام","title":"اتى تاوبني الاحزان والسهر","page":"","text":"اتى تاوبني الاحزان والسهر … فالعين مني هدوءا دمعها درر\nتبكي لصخر وقد راب الزمان به … اذ غاله حدث الايام والقدر\nسمح خلائقه جزل مواهبه … وافي الذمام إذا ما معشر غدروا\nمأوى الضريك ومأوى كل ارملة … عند المحول إذ ما هبت القرر\nما بارز القرن يوما عند معركة … الا له يوم تسمو الكرة الظفر"},{"id":"diwan-khansa:37","bookId":"diwan-khansa","type":"poem","seq":37,"chapter":"البحر: بسيط تام","title":"عيني جودا بدمع غير منزور","page":"","text":"عيني جودا بدمع غير منزور … وأعولا ! إن صخرا خير مقبور\nلا تخذلاني فإني غير ناسية … لذكر صخر حليف المجد والخير\nيا صخر ! من لطراد الخيل إذ وزعت … وللمطايا اذا يشددن بالكور\nولليتامى وللأضياف إن طرقوا … أبياتنا لفعال منك مخبور\nومن لكربة عان في الوثاق ، ومن … يعطي الجزيل على عسر وميسور\nومن لطعنة حلس أو لهاتفة … يوم الصياح بفرسان مغاوير\nفر الاقارب عنها بعد ما ضربوا … بالمشرفية ضربا غير تعزير\nوأسلمت بعد نقف البيض ، واعتسفت … من بعد لذة عيش غير مقتور\nيا صخر كنت لنا عيشا نعيش به … لو أمهلتك ملمات المقادير\nيا فارس الخيل إن شدوا فلم يهنوا … وفارس القوم ان هموا بتقصير\nيا لهف نفسي على صخر إذا ركبت … خيل لخيل كأمثال اليعافير\nوالقح القوم حربا ليس يلقحها … إلا المساعير أبناء المساعير\nيا صخر ماذا يواري القبر من كرم … ومن خلائق عفات مطاهير"},{"id":"diwan-khansa:38","bookId":"diwan-khansa","type":"poem","seq":38,"chapter":"البحر: بسيط تام","title":"يا عين جودي بدمع غير منزور","page":"","text":"يا عين جودي بدمع غير منزور … مثل الجمان على الخدين محدور\nوابكي اخا كان محمودا شمائله … مثل الهلال منيرا غير مغمور\nوفارس الخيل وافته منيته … ففي فؤادي صدع غير مجبور\nنعم الفتى كنت إذ حنت مرفرفة … هوج الرياح حنين الوله الحور\nوالخيل تعثر بالأبطال عابسة … مثل السراحين من كاب ومعفور"},{"id":"diwan-khansa:39","bookId":"diwan-khansa","type":"poem","seq":39,"chapter":"البحر: سريع","title":"يا عين جودي بالدموع الغزار","page":"","text":"يا عين جودي بالدموع الغزار … وابكي على اروع حامي الذمار\nفرع من القوم الجدى … أنماه منهم كل محض النجار\nأقول لما جاءني هلكه … وصرح الناس بنجوى السرار\nأخي ! إما تك ودعتنا … فرع من القوم كريم الجدا\nفرب عرف كنت أسديته … الى عيال ويتامى صغار\nورب نعمى منك انعمتها … على عناة غلق في الإسار\nأهلي فداء للذي غودرت … أعظمه تلمع بين الخبار\nصريع أرماح ومشحوذة … كالبرق يلمعن خلال الديار\nمن كان يوما باكيا سيدا … فليبكه بالعبرات الحرار\nولتبكه الخيل اذا غودرت … بساحة الموت غداة العثار\nوليبكه كل اخي كربة … ضاقت عليه ساحة المستجار\nربيع هلاك ومأوى ندى … حين يخاف الناس قحط القطار\nأسقى بلادا ضمنت قبره … صوب مرابيع الغيوث السوار\nوما سؤالي ذاك الا لكي … يسقاه هام بالروي في القفار\nقل للذي أضحى به شامتا : … إنك والموت ، معا ، في شعار\nهون وجدي أن من سره … مصرعه لاحقه لا تمار\nوانما بينهما روحة … في إثر غاد سار حد النهار\nيا ضارب الفارس يوم الوغى … بالسيف في الحومة ذات الاوار\nيردي به في نقعها سابح … أجرد كالسرحان ثبت الحضار\nنازلت ابطالا لها ذادة … حتى ثنوا عن حرمات الذمار\nحلفت بالبيت وزواره … إذ يعملون العيس نحو الجمار\nلا أجزع الدهر على هالك … بعدك ما حنت هوادي العشار\nيا لوعة بانت تباريحها … تقدح في قلبي شجا كالشرار\nابدى لي الجفوة من بعده … من كان من ذي رحم أو جوار\nإن يك هذا الدهر أودى به … وصار مسحا لمجاري القطار\nفكل حي صائر للبلى … وكل حبل مرة لاندثار"},{"id":"diwan-khansa:40","bookId":"diwan-khansa","type":"poem","seq":40,"chapter":"البحر: كامل تام","title":"يا صخر ! من لحوادث الدهر","page":"","text":"يا صخر ! من لحوادث الدهر … أم من يسهل راكب الوعر\nكنت المفرج ما ينوب فقد … اصبحت لا تحلي ولا تمري\nيحثى التراب على محاسنه … وعلى غضارة وجهه النضر"},{"id":"diwan-khansa:41","bookId":"diwan-khansa","type":"poem","seq":41,"chapter":"البحر: وافر تام","title":"دعوتم عامرا فنبذتموه","page":"","text":"دعوتم عامرا فنبذتموه … ولم تدعوا معاوية بن عمر\nولو ناديته لأتاك يسعى … حثيث الركض او لاتاك يجري\nمدلا حين تشتجر العوالي … ويدرك وتره في كل وتر\nاذا لاقى المنايا لا يبالي … افي يسر اتاه ام بعسر\nكمثل الليث مفترش يديه … جريء الصدر رئبال سبطر"},{"id":"diwan-khansa:42","bookId":"diwan-khansa","type":"poem","seq":42,"chapter":"البحر: بسيط تام","title":"كنا كانجم ليل وسطها قمر","page":"","text":"كنا كانجم ليل وسطها قمر … يجلو الدجى فهوى من بيننا القمر\nيا صخر ! ما كنت في قوم أسر بهم … إلا وإنك بين القوم مشتهر\nفاذهب حميدا على ما كان من حدث … فقد سلكت سبيلا فيه معتبر"},{"id":"diwan-khansa:43","bookId":"diwan-khansa","type":"poem","seq":43,"chapter":"البحر: بسيط تام","title":"كنا كغصنين في جرثومة بسقا","page":"","text":"كنا كغصنين في جرثومة بسقا … حينا على خير ما ينمى له الشجر\nحتى اذا قيل قد طالت عروقهما … وطاب غرسهما واستوسق الثمر\nأخنى على واحد ريب الزمان ، وما … يبقي الزمان على شيء ولا يذر"},{"id":"diwan-khansa:44","bookId":"diwan-khansa","type":"poem","seq":44,"chapter":"البحر: بسيط تام","title":"يا عين جودي بدمع منك مدرار","page":"","text":"يا عين جودي بدمع منك مدرار … جهد العويل كماء الجدول الجاري\nوابكي اخاك ولاتنسي شمائله … وابكي اخاك شجاعا غير خوار\nوابكي اخاك لا يتام وارملة … وابكي اخاك لحق الضيف والجار\nجم فواضله تندى أنامله … كالبدر يجلو ولا يخفى على الساري\nرداد عارية فكاك عانية … كضيغم باسل للقرن هصار\nجواب أودية حمال ألوية … سمح اليدين جواد غير مقتار"},{"id":"diwan-khansa:45","bookId":"diwan-khansa","type":"poem","seq":45,"chapter":"البحر: طويل","title":"الا ابكي على صخر وصخر ثمالنا","page":"","text":"الا ابكي على صخر وصخر ثمالنا … اذا الحرب هرت واستمرت مريرها\nاقام جناحي ربها وترافدوا … على صعبها حتى استقام عسيرها\nببارقة للموت فيها عجاجة … مناكبها مسمومة ونحورها\nأهل بها وكف الدماء ورعدها … هماهم أبطال قليل فتورها\nفصخر لديها مدره الحرب كلها … وصخر اذا خان الرجال يطيرها\nمن الهضبة العليا التي ليس كالصفا … صفاها وما ان كالصخور صخورها\nلها شرفات لاتنال ومنكب … منيع الذرى عال على من يثيرها\nله بسطتا مجد فكف مفيدة … وأخرى بأطراف القناة شقورها\nمن الحرب ربته فليس بسائم … إذا مل عنها ذات يوم ضجورها\nاذا ما اقمطرت للمغار وايقنت … به عن حيال ملقح من يبورها"},{"id":"diwan-khansa:46","bookId":"diwan-khansa","type":"poem","seq":46,"chapter":"البحر: متقارب تام","title":"تعرقني الدهر نهسا وحزا","page":"","text":"تعرقني الدهر نهسا وحزا … وأوجعني الدهر قرعا وغمزا\nوافنى رجالي فبادروا معا … فغودر قلبي بهم مستفزا\nكأن لم يكونوا حمى يتقى … اذ الناس اذ ذاك من عزبزا\nوكانوا سراة بني مالك … وزين العشيرة بذلا وعزا\nوهم في القديم اساة العديم … والكائنون من الخوف حرزا\nوهم منعوا جارهم والنسا … يحفز أحشاءها الخوف حفزا\nغداة لقوهم بملمومة … رداح تغادر في الارض وكرا\nببيض الصفاح وسمر الرماح … فبالبيض ضربا وبالسمر وخزا\nوخيل تكدس بالدارعين … وتحت العجاجة يجمزن جمزا\nومن ظن ممن يلاقي الحروب … بان لا يصاب فقد ظن عجزا\nنعف ونعرف حق القرى … ونتخذ الحمد ذخرا وكنزا\nونلبس في الحرب نسج الحديد … ونسحب في السلم خزا وقزا"},{"id":"diwan-khansa:47","bookId":"diwan-khansa","type":"poem","seq":47,"chapter":"البحر: بسيط تام","title":"بني سليم ! ألا تبكون فارسكم ؟","page":"","text":"بني سليم ! ألا تبكون فارسكم ؟ … خلى عليكم امورا ذات امراس\nما للمنايا تغادينا وتطرقنا … كاننا ابدا نحتز بالفاس\nتغدو علينا فتأبى أن تزايلنا … للخير فالخير منا رهن ارماس\nولايزال حديث السن مقتبلا … وفارسا لا يرى مثل له راس\nمنا يغافضه لو كان يمنعه … بأس لصادفنا حيا أولي باس"},{"id":"diwan-khansa:48","bookId":"diwan-khansa","type":"poem","seq":48,"chapter":"البحر: وافر تام","title":"يؤرقني التذكر حين أمسي","page":"","text":"يؤرقني التذكر حين أمسي … فأصبح قد بليت بفرط نكس\nعلى صخر ، وأي فتى كصخر … ليوم كريهة وطعان حلس\nوللخصم الالد اذا تعدى … ليأخذ حق مظلوم بقنس\nفلم ار مثله رزءا لجن … ولم أر مثله رزءا لإنس\nاشد على صروف الدهر ايدا … وأفصل في الخطوب بغير لبس\nوضيف طارق أو مستجير … يروع قلبه من كل جرس\nفاكرمه وآمنه فامسى … خليا باله من كل بؤس\nيذكرني طلوع الشمس صخرا … وأذكره لكل غروب شمس\nولولا كثرة الباكين حولي … على اخوانهم لقتلت نفسي\nولكن لاازال ارى عجولا … وباكية تنوح ليوم نحس\nأراها والها تبكي أخاها … عشية رزئه او غب امس\nوما يبكون مثل أخي ولكن … اعزي النفس عنه بالتأسي\nفلا والله لا انساك حتى … افارق مهجتي ويشق رمسي\nفقد ودعت يوم فراق صخر … أبي حسان لذاتي وأنسي\nفيا لهفي عليه ولهف امي … ايصبح في الضريح وفيه يمسي"},{"id":"diwan-khansa:49","bookId":"diwan-khansa","type":"poem","seq":49,"chapter":"البحر: مجزوء الكامل","title":"يا عين إبكي فارسا","page":"","text":"يا عين إبكي فارسا … حسن الطعان على الفرس\nذا مرة ومهابة … بينا نؤمله اختلس\nبينا نراه باديا … يحمي كتيبته شرس\nكالليث خف لغيله … يحمي فريسته شكس\nيذر الكمي مجدلا … ترب المناحر منقعس\nخضب السنان بطعنة … فالنفس يحفزها النفس\nفالطير بين مراود … يدنو وآخر منتهس\nنعم الفتى عند الوغى … حين التصايح في الغلس\nفلأبكينك سيدا … فصل الخطاب اذا التبس\nمن ذا يقوم مقامه … بعد ابن امي اذ رمس\nأو من يعود بحلمه … عند التنازع في الشكس\nغيث العشيرة كلها … الغائرين ومن جلس"},{"id":"diwan-khansa:50","bookId":"diwan-khansa","type":"poem","seq":50,"chapter":"البحر: بسيط تام","title":"إن الزمان وما يفنى له عجب","page":"","text":"إن الزمان وما يفنى له عجب … ابقى لنا ذنبا واستوصل الراس\nابقى لنا كل مجهول وفجعنا … بالحالمين فهم هام وأرماس\nان الجديدين في طول اختلافهما … لا يفسدان ولكن يفسد الناس"},{"id":"diwan-khansa:51","bookId":"diwan-khansa","type":"poem","seq":51,"chapter":"البحر: كامل تام","title":"اما ليالي كنت جارية","page":"","text":"اما ليالي كنت جارية … فحففت بالرقباء والجلس\nحتى اذا ما الخدر ابرزني … نبذ الرجال بزولة جلس\nوبجارة شوهاء ترقبني … وحما يخر كمنبذ الحلس"},{"id":"diwan-khansa:52","bookId":"diwan-khansa","type":"poem","seq":52,"chapter":"البحر: وافر تام","title":"ألا يا عين ويحك أسعديني","page":"","text":"ألا يا عين ويحك أسعديني … لريب الدهر والزمن العضوض\nولا تبقي دموعا بعد صخر … فقد كلفت دهرك ان تفيضي\nففيضي بالدموع على كريم … رمته الحادثات ولا تغيضي\nفقد اصبحت بعد فتى سليم … افرج هم صدري بالقريض\nأسائل كل والهة هبول … براها الدهر كالعظم المهيض\nواصبح لا اعد صحيح جسم … ولا دنفا أمرض كالمريض\nولكني ابيت لذكر صخر … أغص بسلسل الماء الغضيض\nوأذكره إذا ما الأرض أمست … هجولا لم تلمع بالوميض\nفمن للحرب إذا صارت كلوحا … وشمر مشعلوها للنهوض\nوخيل قد دلفت لها بأخرى … كان زهاؤها سند الحضيض\nاذا ما القوم احربهم تبول … كذاك التبل يطلب كالقروض\nبكل مهند عضب حسام … رقيق الحد مصقول رحيض"},{"id":"diwan-khansa:53","bookId":"diwan-khansa","type":"poem","seq":53,"chapter":"البحر: طويل","title":"لقد صوت الناعي بفقد اخي الندى","page":"","text":"لقد صوت الناعي بفقد اخي الندى … نداء لعمري لا ابا لك يسمع\nفقمت وقد كادت لروعة هلكه … وفزعته نفسي من الحزن تتبع\nإليه كأني حوبة وتخشعا … أخو الخمر يسمو تارة ثم يصرع\nفمن لقرى الأضياف بعدك إن هم … قبالك حلوا ثم نادوا فأسمعوا\nكعهدهم اذ انت حي واذ لهم … لديك منالات وري ومشبع\nومن لمهم حل بالجار فادح … وأمر وهى من صاحب ليس يرقع\nومن لجليس مفحش لجليسه … عليه بجهل جاهدا يتسرع\nولو كنت حيا كان اطفاء جهله … بحلمك في رفق وحلمك اوسع\nوكنت إذا ما خفت إرداف عسرة … اظل لها من خيفة اتقنع\nدعوت لها صخر الندى فوجدته … له موسر ينفى به العسر اجمع"},{"id":"diwan-khansa:54","bookId":"diwan-khansa","type":"poem","seq":54,"chapter":"البحر: متقارب تام","title":"الا ما لعينك لا تهجع","page":"","text":"الا ما لعينك لا تهجع … تبكي لو ان البكا ينفع\nكان جمانا هوى مرسلا … دموعهما أو هما أسرع\nتحدر وانبت منه النظام … م فانسل من سلكه اجمع\nفبكي لصخر ولا تندبي … سواه فان الفتى مصقع\nمضى وسنمضي على إثره … كذاك لكل فتى مصرع\nهو الفارس المستعد الخطيب … م في القوم واليسر الوعوع\nوعان يحك ظنابيبه … إذا جر في القد لا يرفع\nدعاك فهتكت أغلاله … وقد ظن قبلك لا تقطع\nوجلس أمون تسديتها … ليطعمها نفر جوع\nفظلت تكوس على اكرع … ثلاث وكان لها أربع\nبمهو اذا انت صوبته … كان العظام له خروع"},{"id":"diwan-khansa:55","bookId":"diwan-khansa","type":"poem","seq":55,"chapter":"البحر: متقارب تام","title":"أبى طول ليلى لا أهجع","page":"","text":"أبى طول ليلى لا أهجع … وقد عالني الخبر الأشنع\nنعي ابن عمر واتى موهنا … قتيلا فما لي لا اجزع\nوفجعني ريب هذا الزمان … به والمصائب قد تفجع\nفمثل حبيبي أبكى العيون … وأوجع من كان لا يوجع\nأخ لي لا يشتكيه الرفيق … ولا الركب في الحاجة الجوع\nويهتز في الحرب عند النزال … كما اهتز ذو الرونق المقطع\nفما لي وللدهر ذي النائبات … اكل الوزوع بنا توزع"},{"id":"diwan-khansa:56","bookId":"diwan-khansa","type":"poem","seq":56,"chapter":"البحر: بسيط تام","title":"يا أم عمر وألا تبكين معولة","page":"","text":"يا أم عمر وألا تبكين معولة … على اخيك وقد اعلى به الناعي\nفابكي ولا تسأمي نوحا مسلبة … على اخيك رفيع الهم والباع\nفقد فجعت بميمون نقيبته … جم المخارج ضرار ونفاع\nفمن لنا إن رزئناه وفارقنا … بسيد من وراء القوم دفاع\nقد كان سيدنا الداعي عشيرته … لا تبعدن ، فنعم السيد الداعي"},{"id":"diwan-khansa:57","bookId":"diwan-khansa","type":"poem","seq":57,"chapter":"البحر: طويل","title":"تذكرت صخرا إذ تغنت حمامة","page":"","text":"تذكرت صخرا إذ تغنت حمامة … هتوف على غصن من الأيك تسجع\nفظلت لها أبكي بدمع حزينة … وقلبي مما ذكرتني موجع\nتذكرني صخرا وقد حال دونه … صفيح وأحجار وبيداء بلقع\nارى الدهر يرمي ماتطيش سهامه … وليس لمن قد غاله الدهر مرجع\nفإن كان صخر الجود أصبح ثاويا … فقد كان في الدنيا يضر وينفع"},{"id":"diwan-khansa:58","bookId":"diwan-khansa","type":"poem","seq":58,"chapter":"البحر: طويل","title":"أقسمت لا أنفك أهدي قصيدة","page":"","text":"أقسمت لا أنفك أهدي قصيدة … لصخر أخي المفضال في كل مجمع\nفدتك سليم كهلها وغلامها … وجدع منها كل انف ومسمع"},{"id":"diwan-khansa:59","bookId":"diwan-khansa","type":"poem","seq":59,"chapter":"البحر: بسيط تام","title":"يا عين بكي بدمع غير إنزاف","page":"","text":"يا عين بكي بدمع غير إنزاف … وابكي لصخر فلن يكفيكه كاف\nكوني كورقاء في أفنان غيلتها … او صائح في فروع النخل هتاف\nوابكي على عارض بالودق محتفل … إذا تهاونت الأحساب رجاف\nومنزل الضيف ان هبت مجلجلة … ترمي بصم سريع الخسف رساف\nأبي اليتامى إذا ما شتوة نزلت ؛ … وفي المزاحف ثبت غير وجاف"},{"id":"diwan-khansa:60","bookId":"diwan-khansa","type":"poem","seq":60,"chapter":"البحر: خفيف تام","title":"ما لذا الموت لا يزال مخيفا","page":"","text":"ما لذا الموت لا يزال مخيفا … كل يوم ينال منا شريفا\nمولعا بالسراة منا ، فما يأخذ … خذ الا المهذب الغطريفا\nفلو ان المنون تعدل فينا … فتنال الشريف والمشروفا\nكان في الحق أن يعود لنا الموت … وأن لا نسومه تسويفا\nايها الموت لو تجافيت عن صخر … م لالفيته نقيا عفيفا\nعاش خمسين حجة ينكر المنكر … م فينا ويبذل المعروفا\nرحمة الله والسلام عليه … وسقى قبره الربيع خريفا"},{"id":"diwan-khansa:61","bookId":"diwan-khansa","type":"poem","seq":61,"chapter":"البحر: بسيط تام","title":"يا لهف نفسي على صخر وقد لهفت","page":"","text":"يا لهف نفسي على صخر وقد لهفت … وهل يردن خبل القلب تلهيفي\nابكي اخاك اذا جاورتهم سحرا … جودي عليه بدمع غير منزوف\nابكي المهين تلاد المال ان نزلت … شهباء ترزح بالقوم المتاريف\nوابكي اخاك لدهر صار مؤتلفا … والدهر ، ويحك ، ذو فجع وتجليف"},{"id":"diwan-khansa:62","bookId":"diwan-khansa","type":"poem","seq":62,"chapter":"قصائد","title":"مرهت عيني فعيني","page":"","text":"مرهت عيني فعيني … بعد صخر عطفه\nفدموع العين مني … فوق خدي وكفه\nطرفت حندر عيني … بعكيك ذرفه\nان نفسي بعد صخر … بالردى معترفه\nوبها من صخر شيء … ليس يحكى بالصفه\nوبنفسي لهموم … فهي حرى آسفه\nوبذكرى صخر نفسي … كل يوم كافه\nإن صخرا كان حصنا … وربى للنطفه\nوغياثا وربيعا … للعجوز الخرفه\nواذا هبت شمال … او جنوب عصفه\nنحر الكوم الصفايا … والبكار الخلفه\nيملأ الجفنة شحما … قتراها سدفه\nوترى الهلاك شبعى … نحوها مزدلفه\nوترى الايدي فيها … دسمات غدفه\nواردات صادرات … كقطا مختلفه\nكدبور وشمال … في حياض لقفه\nفلئن أجرع صخر … اصبحت لي ظلفه\nانها كانت زمانا … روضة مؤتنفه"},{"id":"diwan-khansa:63","bookId":"diwan-khansa","type":"poem","seq":63,"chapter":"البحر: وافر تام","title":"هريقي من دموعك أو افيقي","page":"","text":"هريقي من دموعك أو افيقي … وصبرا ان اطقت ولن تطيقي\nوقولي إن خير بني سليم … وفارسهم بصحراء العقيق\nواني والبكا من بعد صخر … كسالكة سوى قصد الطريق\nفلا وابيك ما سلبت صدري … بفاحشة أتيت ولا عقوق\nولكني وجدت الصبر خيرا … من النعلين والرأس الحليق\nألا هل ترجعن لنا الليالي … وايام لنا بلوى الشقيق\nألا يا لهف نفسي بعد عيش … لنا بندى المختم والمضيق\nواذ فينا فوارس كل هيجا … إذا فزعوا وفتيان الخروق\nإذا ما الحرب صلصل ناجذاها … وفاجاها الكماة لدى البروق\nواذ فينا معاوية بن عمر و … على ادماء كالجمل الفنيق\nفبكيه فقد ولى حميدا … أصيل الرأي محمود الصديق\nهو الرزء المبين لا كباس … عظيم الرأي يحلم بالنعيق"},{"id":"diwan-khansa:64","bookId":"diwan-khansa","type":"poem","seq":64,"chapter":"البحر: بسيط تام","title":"يا عين جودي بدمع منك مهراق","page":"","text":"يا عين جودي بدمع منك مهراق … اذا هدى الناس أو هموا باطراق\nاني تذكرني صخرا اذا سجعت … على الغصون هتوف ذات أطواق\nوكل عبرى تبيت الليل ساهرة … تبكي بكاء حزين القلب مشتاق\nلا تكذبن فإن الموت مخترم … كل البرية غير الواحد الباقي\nانت الفتى الماجد الحامي حقيقته … تعطي الجزيل بوجه منك مشراق\nوالعود تعطي معا والناب مكتنفا … وكل طرف الى الغايات سباق\nاني سابكي ابا حسان نادبة … ما زلت في كل امساء واشراق"},{"id":"diwan-khansa:65","bookId":"diwan-khansa","type":"poem","seq":65,"chapter":"البحر: طويل","title":"آمن حدث الايام عينك تهمل","page":"","text":"آمن حدث الايام عينك تهمل … تبكي على صخر وفي الدهر مذهل\nالا من لعين لا تجف دموعها … إذا قلت أفثت تستهل فتحفل\nعلى ماجد ضخم الدسيعة بارع … له سورة في قومه ما تحول\nفما بلغت كف امرىء متناول … من المجد إلا حيث ما نلت أطول\nولا بلغ المهدون في القول مدحة … ولا صدقوا إلا الذي فيك أفضل\nوما الغيث في جعد الثرى دمث الربى … تبعق فيه الوابل المتهلل\nباوسع سيبا من يديك ونعمة … تعم بها بل سيب كفيك أجزل\nوجارك محفوظ منيع بنجوة … من الضيم لا يؤذى ولا يتذلل\nمن القوم مغشي الرواق كأنه … اذا سيم ضيما خادر متبسل\nشرنبت اطراف البنان ضبارم … له في عرين الغيل عرس واشبل\nهزبر هريت الشدق رئبال غابة … مخوف اللقاء جائب العين انجل\nأخو الجود معروف له الجود والندى … حليفان ما دامت تعار ويذبل"},{"id":"diwan-khansa:66","bookId":"diwan-khansa","type":"poem","seq":66,"chapter":"البحر: وافر تام","title":"أيا عيني ويحكما استهلا","page":"","text":"أيا عيني ويحكما استهلا … بدمع غير منزور وعلا\nبدمع غير دمعكما وجودا … فقد اورثتما حزنا وذلا\nعلى صخر الأغر أبي اليتامى … ويحمل كل معثرة وكلا\nفان اسعفتماني فارفداني … بدمع يخضل الخدين بلا\nعلى صخر بن عمر وإن هذا … وإن قد قل بحرك واضمحلا\nفقد اورثتما حزنا وذلا … وحرا في الجوانب مستقلا\nفقومي يا صفية في نساء … بحر الشمس لا يبغين ظلا\nيشققن الجيوب وكل وجه … طفيف أن تصلي له وقلا"},{"id":"diwan-khansa:67","bookId":"diwan-khansa","type":"poem","seq":67,"chapter":"البحر: وافر تام","title":"بكت عيني وحق لها العويل","page":"","text":"بكت عيني وحق لها العويل … وهاض جناحي الحدث الجليل\nفقدت الدهر ، كيف أكل ركني … لأقوام مودتهم قليل\nعلى نفرهم كانوا جناحي … عليهم حين تلقاهم قبول\nفذكرني أخي قوما تولوا … علي بذكرهم ما قيل قيل\nمعاوية بن عمر وكان ركني … وصخرا كان ظلهم الظليل\nذكرت فغالني ونكا فؤادي … وارق قومي الحزن الطويل\nأولو عز كانهم غضاب … ومجد مده الحسب الطويل\nهم سادوا معدا في صباهم … وسادوا وهم شباب او كهول\nفبكي أم عمر وكل يوم … اخا ثقة محياه جميل"},{"id":"diwan-khansa:68","bookId":"diwan-khansa","type":"poem","seq":68,"chapter":"البحر: طويل","title":"آلا ليت أمي لم تلدني سوية","page":"","text":"آلا ليت أمي لم تلدني سوية … وكنت ترابا بين أيدي القوابل\nوخرت على الأرض السماء فطبقت … ومات جميعا كل جاف وناعل\nغداة غدا ناع لصخر فراعني … وأورثني حزنا طويل البلابل\nفقلت له : ماذا تقول ؟ فقال لي : … نعى ما ابن عمر واثكلته هوابلي\nفأصبحت لا التذ بعدك نعمة … حياتي ولا ابكي لدعوة ثاكل\nفشأن المنايا بالاقارب بعده … لتعلل عليهم علة بعد ناهل"},{"id":"diwan-khansa:69","bookId":"diwan-khansa","type":"poem","seq":69,"chapter":"البحر: سريع","title":"يا عين جودي بالدموع السجول","page":"","text":"يا عين جودي بالدموع السجول … وابكي على صخر بدمع همول\nلا تخذليني عند جد البكا … فليس ذا يا عين وقت الخذول\nابكي ابا حسان واستعبري … على الجميل المستضاف المخيل\nنعم اخو الشتوة حلت به … أرامل الحي غداة البليل\nيأتينه مستعصمات به … يعلن في الدار بدعوى الآليل\nونعم جار القوم في ازمة … اذا التجا الناس بجار ذليل\nدل على معروفه وجهه … بورك فيها هاديا من دليل\nلا يقصر الفضل على نفسه … بل عنده من نابه في فضول\nقد عرف الناس له انه … بالمنزل الا تلع غير الضئيل\nعطاؤه جزل وصولاته … صولات قرم لقروم صؤول\nورأيه حكم وفي قوله … مواعظ يذهبن داء الغليل\nليس نجب مانع ظهره … لا ينهض الدهر بعبء ثقيل\nولا بسعال اذا يجتدى … وضاق بالمعروف صدر السعول\nقد راعني الدهر فبؤسا له … بفارس الفرسان والخنشليل\nتركتني وسط بني علة … ادور فيهم كاللعين النقيل"},{"id":"diwan-khansa:70","bookId":"diwan-khansa","type":"poem","seq":70,"chapter":"البحر: سريع","title":"ان ابا حسان عرش هوى","page":"","text":"ان ابا حسان عرش هوى … مما بنى الله بكن ظليل\nاتلع لا يغلبه قرنه … مستجمع الرأي عظيم طويل\nتحسبه غضبان من عزه … ذلك منه خلق ما يحول\nويل امه مسعر حرب إذا … ألقي فيها فارسا ذا شليل\nتشقى به الكوم لدى قدره … والناب والمصعبة الخنشليل\nانى لي الفارس اغدو به … مثلك إذا ما حملتني الحمول\nتركتني يا صخر في فتية … كأنني بعدك فيهم نقيل"},{"id":"diwan-khansa:71","bookId":"diwan-khansa","type":"poem","seq":71,"chapter":"البحر: مجزوء الكامل","title":"ابكي على البطل الذي","page":"","text":"ابكي على البطل الذي … جللتم صخرا ثقالا\nمتحزما بالسيف يركب … كب رمحه حالا فحالا\nيا صخر من للخيل إذ … ردت فوارسها عجالا\nمتسربلي حلق الحديد … تخالهم فيه جمالا\nويلي عليك إذا تهب … الريح باردة شمالا\nوالحيدر الصراد لم … يك غيمها إلا طلالا\nليروع القوم الذين … نعدهم فينا عيالا\nخير البرية في قرى … صخر واكرمهم فعالا\nوهو المؤمل والذي … يرجى وأفضلها نوالا"},{"id":"diwan-khansa:72","bookId":"diwan-khansa","type":"poem","seq":72,"chapter":"البحر: متقارب تام","title":"أعيني فيضي ولا تبخلي","page":"","text":"أعيني فيضي ولا تبخلي … فإنك للدمع لم تبذلي\nوجودي بدمعك واستعبري … كسح الخليج على الجدول\nعلى خير من يندب المعولون … ن والسيد الايد الافضل\nطويل النجاد رفيع العما … ليس بوغد ولا زمل\nيحيد الكفاح غداة الصيا … حامي الحقيقة لم ينكل\nكان العداة اذا ما بدا … يخافون وردا ابا اشبل\nمدلا من الأسد ذا لبدة … حمى الجزع منه فلم ينزل\nيعف ويحمي إذا ما اعتزى … إلى الشرف الباذخ الأطول\nيحامي عن الحي يوم الحفا … ظ والجار والضيف والنزل\nومستنة كاستنان الخليج م … فوارة الغمر كالمرجل\nرموح من الغيظ رمح الشموس … تلافيت في السلف الاول\nلتبك عليك عيال الشتاء … اذا الشول لاذت من الشمأل"},{"id":"diwan-khansa:73","bookId":"diwan-khansa","type":"poem","seq":73,"chapter":"البحر: وافر تام","title":"ألا يا صخر إن أبكيت عيني","page":"","text":"ألا يا صخر إن أبكيت عيني … لقد أضحكتني دهرا طويلا\nبكيتك في نساء معولات … وكنت احق من ابدى العويلا\nدفعت بك الجليل وأنت حي … فمن ذا يدفع الخطب الجليلا\nإذا قبح البكاء على قتيل … رأيت بكاءك الحسن الجميلا"},{"id":"diwan-khansa:74","bookId":"diwan-khansa","type":"poem","seq":74,"chapter":"البحر: متقارب تام","title":"الا ما لعينك ام مالها","page":"","text":"الا ما لعينك ام مالها … لقد أخضل الدمع سربالها\nابعد ابن عمر ومن آل الشريد م … حلت به الأرض أثقالها\nفآليت آسى على هالك … وأسأل باكية ما لها\nلعمر أبيك ، لنعم الفتى … تحش به الحرب أجذالها\nحديد السنان ذليق اللسان … يجازي المقارض أمثالها\nهممت بنفسي كل الهموم … فاولى لنفسي اولى لها\nسأحمل نفسي على آلة … فإما عليها وإما لها\nفإن تصبر النفس تلق السرور ، … وإن تجزع النفس أشقى لها\nنهين النفوس ، وهون النفوس … س يوم الكريهة ابقى لها\nونعلم ان منايا الرجا … ل بالغة حيث يحلى لها\nلتجر المنية بعد الفتى م … المغادر بالمحو أذلالها\nورجراجة فوقها بيضها … عليها المضاعف أمثالها\nككرفئة الغيث ذات الصبير م … ترمي السحاب ويرمى لها\nوخيل تكدس بالدارعين … نازلت بالسيف ابطالها\nوقافية مثل حد السنا … ن تبقى ويذهب من قالها\nتقد الذؤابة من يذبل ، … أبت أن تفارق أوعالها\nنطقت ابن عمر وفسهلتها … ولم ينطق الناس أمثالها\nفإن تك مرة أودت به … فقد كان يكثر تقتالها\nفخر الشوامخ من قتله … وزلزلت الأرض زلزالها\nوزال الكواكب من فقده … وجللت الشمس أجلالها\nوداهية جرها جارم … تبين الحواضن احمالها\nكفاها ابن عمر وولم يستعن … ولو كان غيرك أدنى لها\nوليس بأولى ولكنه … سيكفي العشيرة ما غالها\nبمعترك ضيق بينه … تجر المنية أذيالها\nتطاعنها فإذا أدبرت … بللت من الدم اكفالها\nوبيض منعت غداة الصيا … تكشف للروع أذيالها\nومعملة سقتها قاعدا … فاعلمت بالسيف اغفالها\nوناجية كأتان الثميل … غادرت بالخل أوصالها\nالى ملك لا الى سوقة … وذلك ما كان اكلا لها\nوتمنح خيلك ارض العدى … وتنبذ بالغزو أطفالها\nونوح بعثت كمثل الارا … آنست العين أشبالها"},{"id":"diwan-khansa:75","bookId":"diwan-khansa","type":"poem","seq":75,"chapter":"البحر: طويل","title":"لما رأيت البدر أظلم كاسفا","page":"","text":"لما رأيت البدر أظلم كاسفا … أرن شواذ بطنه وسوائله\nرنينا وما يغني الرنين وقد اتى … بموتك من نحو القرية حامله\nلقد خار مرداسا على الناس قاتله … ولو عاده كناته وحلائله\nوقلن الاهل من شفاء يناله … وقد منع الشفاء من هو نائله\nوفضل مرداساعلى الناس حلمه … وان كل هم همه فهو فاعله\nوان كل واد يكره الناس هبطه … هبطت وماء منهل انت ناهله\nتركت به ليلا طويلا ومنزلا … تعادى على ظهر الطريق عواسله\nوسبي كآرام الصريم تركته … خلال الديار مستكينا عواطله\nوعدت عليهم بعد بؤسي بانعم … فكلهم تعنى به وتواصله\nمتى ما توازن ماجدا يعتدل به ، … كما عدل الميزان بالكف راطله"},{"id":"diwan-khansa:76","bookId":"diwan-khansa","type":"poem","seq":76,"chapter":"البحر: طويل","title":"سقى جدثا اكناف غمرة دونه","page":"","text":"سقى جدثا اكناف غمرة دونه … من الغيث ديمات الربيع ووابله\nأعيرهم سمعي إذا ذكر الأسى … وفي القلب منه زفرة ما تزايله\nوكنت أعير الدمع قبلك من بكى ، … فأنت على من مات بعدك شاغله"},{"id":"diwan-khansa:77","bookId":"diwan-khansa","type":"poem","seq":77,"chapter":"البحر: بسيط تام","title":"كل امرىء باثا في الدهر مرجوم","page":"","text":"كل امرىء باثا في الدهر مرجوم … وكل بيت طويل السمك مهدوم\nلا سوقة منهم يبقى ولا ملك … ممن تملكه الأحرار والروم\nان الحوادث لا يبقى لنائبها … إلا الإله ، وراسي الأصل معلوم\nوقد أتاني حديث غير ذي طيل … من معشر رأيهم قدما تهاميم\nإن الشجاة التي حدثتم اعترضت … خلف اللها لم تسوغها البلاعيم\nإن كان صخر تولى فالشمات بكم … وليس يشمت من كانت له طوم\nمر الحوادث ينقاد الجليد لها … ويستقيم لها الهيابة البوم\nقد كان صخرا جليدا كاملا برعا … جلد المريرة تنميه السلاجيم\nفأصبح اليوم في رمس لدى جدث … وسط الضريح عليه الترب مركوم\nتالله أنسى ابن عمرو الخير ما نطقت … حمامة أو جرى في الغمر علجوم\nأقول صخر لدى الأجداث مرموم ، … وكيف اكتمه والدمع مسجوم"},{"id":"diwan-khansa:78","bookId":"diwan-khansa","type":"poem","seq":78,"chapter":"البحر: وافر تام","title":"فدى للفارس الجشمي نفسي","page":"","text":"فدى للفارس الجشمي نفسي … وأفديه بمن لي من حميم\nوأفديه بكل بني سليم … بظاعنهم وبالانس المقيم\nخصصت بها أخا الأحرار قيسا … فتى في بيت مكرمة كريم"},{"id":"diwan-khansa:79","bookId":"diwan-khansa","type":"poem","seq":79,"chapter":"البحر: طويل","title":"من لامني في حب كوز وذكره","page":"","text":"من لامني في حب كوز وذكره … فلاقى الذي لا قيت إذا حفز الرحم\nفيا حبذا كوز إذا الخيل أدبرت … وثار غبار في الدهاس وفي الاكم\nفنعم الفتى تعشوا إلى ضوء ناره … كويز بن صخر ليلة الريح والظلم\nاذا البازل الكوماء لاذت برفلها … ولاذت لواذا بالمدرين بالسلم\nوقد حال خير من أناس ورفدهم … بكفي غلام لا ضنين ولابرم"},{"id":"diwan-khansa:80","bookId":"diwan-khansa","type":"poem","seq":80,"chapter":"البحر: طويل","title":"لعمري وما عمري علي بهين","page":"","text":"لعمري وما عمري علي بهين … لنعم الفتى أرديتم آل خثعما\nأصيب به فرعا سليم كلاهما … فعز علينا أن يصاب ونرغما\nوكان إذا ما أقدم الخيل بيشة … الى هضب اشراك اناخ فالجما\nفارسلها تهوي رعالا كانها … جراد زفته ريح نجد فأتهما\nفأمسى الحوامي قد تعفين بعده … وكان الحصى يكسو دوابرها دما\nفآبت عشاء بالنهاب وكلها … يرى قلقا تحت الرحالة اهضما\nوكانت اذا لم تطارد بعاقل … او الرس خيلا طاردتها بعيهما\nوكان ثمال الحي في كل ازمة … وعصمتهم والفارس المتغشما\nوينهض للعليا إذا الحرب شمرت … فيطفئها قهرا وان شاء اضرما\nفأقسمت لا أنفك أحدر عبرة … تجول بها العينان مني لتسجما"},{"id":"diwan-khansa:81","bookId":"diwan-khansa","type":"poem","seq":81,"chapter":"البحر: متقارب تام","title":"الا ابلغ سليما واشباعها","page":"","text":"الا ابلغ سليما واشباعها … بانا فضلنا برأس الهمام\nوانا صجناهم غارة … فأروتهم من نقيع السمام\nوعبسا صبحنا بثهلاتهم … بكأس وليس بكأس المدام\nوثعلبة الروع قد عاينوا … خيولا عليها اسود الاجام\nيلوذون منا حذار اللقا … فضربا وطعنا وحسن النظام\nوسقنا لرابمهم سجدا … باحداجها وذوات الجزام"},{"id":"diwan-khansa:82","bookId":"diwan-khansa","type":"poem","seq":82,"chapter":"البحر: مجزوء الكامل","title":"يا عين جودي بالدموع","page":"","text":"يا عين جودي بالدموع … المستهلات السواجم\nفيضا كما انخرق الجمان … ن وجال في سلك النواظم\nوابكي معاوية الفتى … وابن الخضارمة القماقم\nوالحازم الباني العلى … في الشاهقات من الدعائم\nتلقى الجزيل عطاؤه … عند الحقائق غير نادم\nأسقى الإله ضريحه … من صوب دائمة الرهائم"},{"id":"diwan-khansa:83","bookId":"diwan-khansa","type":"poem","seq":83,"chapter":"البحر: طويل","title":"أمن ذكر صخر دمع عينه يسجم","page":"","text":"أمن ذكر صخر دمع عينه يسجم … بدمع حثيث كالجمان المنظم\nفتى كان فينا لم ير الناس مثله … كفالا لأم أو وكيلا لمحرم\nحسيب ينال المجد منه ببسطة … ويعجز عن افضاله كل شظيم\nففرقت فرعيها وكنت سدادها … اذا كان يوم بالغا كل معظم\nوما ضاعت الأرحام عندك والذي … وليت ومااستحفظت فيها لمجرم\nكأن بغاة الخير عندك أصبحوا … على نهج من طافح\nتوسعت للحاجات يا صخر كلها … فحام الى معروفك المتنسم\nوأنت ابن فرع القوم يا صخر كلها … إذا قال فرسان اللقا : صخر أقدم\nاذا ذكرت نفسي نداه وبأسه … تحسر عنها كل عيش وانعم"},{"id":"diwan-khansa:84","bookId":"diwan-khansa","type":"poem","seq":84,"chapter":"البحر: بسيط تام","title":"يا عين بكي على صخر لأشجان","page":"","text":"يا عين بكي على صخر لأشجان … وهاجس في ضمير القلب خزان\nاني ذكرت ندى صخر فهيجني … ذكر الحبيب على سقم واحزان\nفابكي أخاك لأيتام أضر بهم … ريب الزمان ، وكل الضر يغشاني\nوابكي المعمم زين القائدين اذا … كان الرماح لديهم خلج اشطان\nوابن الشريد فلم تبلغ أرومته … عند الفخار لقرم غير مهجان\nلو كان للدهر مال عند متلده … لكان للدهر صخر مال فتيان\nآبي الهضيمة آت بالعظيمة متلاف م … الكريمة لا نكس ولا وان\nحامي الحقيقة بسال الوديقة معتاق … الوسيقة جلد غير ثنيان\nطلاع مرقبة مناع مغلقة … وراد مشربة قطاع أقران\nشهاد أندية حمال ألوية … قطاع اودية سرحان قيعان\nيحمي الصحاب إذا جد الضراب … القائلين اذا ما كيل الهاني\nويترك القرن مصفرا أنامله … كأن في ريطتيه نضح أرقان\nيعطيك ما لاتكاد النفس تسلمه … من التلاد وهوب غير منان"},{"id":"diwan-khansa:85","bookId":"diwan-khansa","type":"poem","seq":85,"chapter":"البحر: بسيط تام","title":"يا لهف نفسي على صخر وقد فزعت","page":"","text":"يا لهف نفسي على صخر وقد فزعت … خيل لخيل وأقران لأقران\nسمح إذا يسر الأقوام أقدحهم … طلق اليدين وهوب غير منان\nحلاحل ماجد محض ضريبته … مجذامة لهواه غير مبطان\nسمح سجيته جزل عطيته … وللأمانة راع غير خوان\nنعم الفتى أنت يوم الروع قد علموا … كفء اذا التف فرسان بفرسان\nسمح الخلائق محمود شمائله … عالي البناء إذا ما قصر الباني\nمأوى الارامل والايتام ان سغبوا … شهاد أنجية مطعام ضيفان\nحلف الندى وعقيد المجد اي فتى … كالليث في الحرب لا نكس ولا وان"},{"id":"diwan-khansa:86","bookId":"diwan-khansa","type":"poem","seq":86,"chapter":"البحر: وافر تام","title":"بكت عيني وعاودها قذاها","page":"","text":"بكت عيني وعاودها قذاها … بعوار فما تقضي كراها\nعلى صخر ، وأي فتى كصخر … إذا ما الناب لم ترأم طلاها\nفتى الفتيان ما بلغوا مداه … ولا يكدى إذا بلغت كداها\nحلفت برب صهب معيلات … الى البيت المحرم منتهاها\nلئن جزعت بنو عمر وعليه … لقد رزئت بنو عمر وفتاها\nله كف يشد بها وكف … تحلب ما يجف ثرى نداها\nترى الشم الجحاجح من سليم … يبل ندى مدامعها لحاها\nعلى رجل كريم الخيم اضحى … ببطن حفيرة صخب صداها\nليبك الخير صخرا من معد … ذوو أحلامها وذوو نهاها\nوخيل قد لففت بجول خيل … فدارت بين كبشيها رحاها\nترفع فضل سابغة دلاص … على خيفانة خفق حشاها\nوتسعى حين تشتجر العوالي … بكأس الموت ساعة مصطلاها\nمحافظة ومحمية اذا ما … نبا بالقوم من جزع لظاها\nفتتركها قد اضطرمت بطعن … تضمنه إذا اختلفت كلاها\nفمن للضيف إن هبت شمال … مزعزعة تجلوبها صباها\nوألجا بردها الأشوال حدبا … الى الحجرات بادية كلاها\nهنالك لو نزلت بآل صخر … قرى الأضياف شحما من ذراها\nفلم املك غداة نعي صخر … سوابق عبرة حلبت صراها\nأمطعمكم وحاملكم تركتم … لدى غبراء منهدم رجاها\nليبك عليك قومك للمعالي … وللهيجاء ، إنك ما فتاها\nوقد فقدتك طلقة فاستراحت … فليت الخيل فارسها يراها"},{"id":"diwan-khansa:87","bookId":"diwan-khansa","type":"poem","seq":87,"chapter":"قصائد","title":"من حس لي الاخوين","page":"","text":"من حس لي الاخوين … كالغصنين أو من راهما\nأخوين كالصقرين لم … ير ناظر شرواهما\nقرمين لا يتظالمان … ولا يرام حماهما\nابكي على اخوي … بالقبر الذي واراهما\nلامثل كهلي في الكهو … ولا فتى كفتاهما\nرمحين خطيين في … كبد السماء سناهما\nما خلفا اذ ودعا … في سؤدد شرواهما\nسادا بغير تكلف … عفوا بفيض نداهما"},{"id":"diwan-khansa:88","bookId":"diwan-khansa","type":"poem","seq":88,"chapter":"البحر: طويل","title":"آلا ايها الديك المنادي بسحرة","page":"","text":"آلا ايها الديك المنادي بسحرة … هلم كذا اخبرك ما قد بدا ليا\nبدا لي أني قد رزئت بفتية … بقية قوم أورثوني المباكيا\nفلما سمعت النائحات ينحنه … تعزيت واستيقنت ان لا اخا ليا\nكصخر بن عمر وخير من قد علمته … وكيف ارجي العيش ضل ضلا ليا\nوما لي لا أبكي على من لو انه … تقدم يومي قبله لبكى ليا\nوان تمس في قيس وزيد وعامر … وغسان لم تسمع له الدهر لاحيا"},{"id":"diwan-khansa:89","bookId":"diwan-khansa","type":"poem","seq":89,"chapter":"البحر: طويل","title":"ارى الدهر افنى معشري وبني ابي","page":"","text":"ارى الدهر افنى معشري وبني ابي … فأمسيت عبرى لا يجف بكائيا\nأيا صخر هل يغني البكاء أو الأسى … على ميت بالقبر أصبح ثاويا\nفلا يبعدن الله صخرا وعهده … ولا يبعدن الله ربي معاويا\nولا يبعدن الله صخرا ، فإنه … أخو الجود يبني للفعال العواليا\nسابكيهما والله ما حن واله … وما أثبت الله الجبال الرواسيا\nسقى الله ارضا اصبحت قد حوتهما … من المستهلات السحاب الغواديا"},{"id":"diwan-khansa:90","bookId":"diwan-khansa","type":"poem","seq":90,"chapter":"البحر: طويل","title":"الا لا ارى في الناس مثل معاويه","page":"","text":"الا لا ارى في الناس مثل معاويه … إذا طرقت إحدى الليالي بداهيه\nبداهية يصغى الكلاب حسيسها … وتخرج من سر النجي علانيه\nالا لا ارى كالفارس الورد فارسا … إذا ما علته جرأة وعلانيه\nوكان لزاز الحرب عند شبوبها … اذا شمرت عن ساقها وهي ذاكيه\nوقواد خيل نحو اخرى كانها … سعال وعقبان عليها زبانيه\nبلينا وما تبلى تعار وما ترى … على حدث الايام الا كماهيه\nفأقسمت لا ينفك دمعي وعولتي … عليك بحزن ما دعا الله داعيه"},{"id":"diwan-khansa:91","bookId":"diwan-khansa","type":"poem","seq":91,"chapter":"البحر: سريع","title":"ابنت صخر تلكما الباكيه","page":"","text":"ابنت صخر تلكما الباكيه … لا باكي الليلة إلا هيه\nاودى ابو حسان واحسرتا … وكان صخر ملك العاليه\nويلاي ! ما أرحم ويلا ليه ، … اذ رفع الصوت الندى الناعيه\nكذبت بالحق وقد رابني … حتى علت ابياتنا الواعيه\nبالسيد الحلو الأمي الذي … يعصمنا في السنة الغاديه\nلكن بعض القوم هيابة … في القوم لا تغبطه الباديه\nلا ينطق العرف ولا يلحن … م العزف ولا ينفد بالغازيه\nان تنصب القدر لدى بيته … فغيرها يحتضر الجاديه\nلكن اخي اروع ذو مرة … من مثله تسترفد الباغيه\nلا ينطق النكر لدى حرة … يبتار خالي الهم في الغاويه\nان اخي ليس بترعية … نكس هواء القلب ذي ماشيه\nعطافه أبيض ذو رونق … كالرجع في المدجنة الساريه\nفوق حثيث الشد ذو ميعة … يقدم أولى العصب الماضيه\nلا خير في عيش وإن سرنا ، … والدهر لا تبقى له باقيه\nكل امرىء مر به اهله … سوف يرى يوما على ناحيه\nيا من يرى من قومنا فارسا … في الخيل إذ تعدو به الضافيه\nتحتك كبداء كميت كما … أدرج ثوب اليمنة الطاويه\nاذ لحقت من خلفها تدعي … مثل سوام الرجل العاديه\nيكفأها بالطعن فيها كما … ثلم باقي جبوة الحابيه\nتهوي اذا ارسلن من منهل … مثل عقاب الدجنة الداجيه\nعارض سحماء ردينية … كالنار فيها آلة ماضيه\nاشربها القين لدى سنها … فصار فيها الحمة القاضيه\nانى لنا اذ فاتنا مثله … للخيل اذ جالت وللعاديه\nأقسم لا يقعد في بلدة … نائية عن أهله قاصيه\nفأقصد السير على وجهه … لم ينهه الناهي ولا الناهيه"}]};